/**
 * 야간 초등학교 캠퍼스 맵 v3 — 80x80
 * campus-data.js에서 자동 생성. 수정은 데이터 쪽에서 하고 다시 내보낼 것.
 *
 * ── 구성 ──
 * 본관(ㄱ자) 3층 + 옥상 : 복도(전 구간 연속) + 교실/특별실 4실/층 + 계단실 베이 3
 *   1F 교실1-1 · 행정실 · 현관 로비 · 보건실 · 화장실 | 윙: 급식실 · 조리실 | 별관: 창고·숙직실(막다른 방)
 *   2F 교실2-1 · 교실2-2 · 과학실(미션) · 교무실 · 화장실 | 윙: 도서실 · 음악실
 *   3F 교실3-1 · 시청각실 · 교실3-2 · 방송실 · 화장실 | 윙: 미술실 · 컴퓨터실
 *   엘리베이터: 관통 승강로 + 가이드 레일 + 균형추 + 로프 + 옥상 권상기/제어반,
 *               카(바닥·3면·천장·거울·손잡이·조작반·조명·층표시)는 ElevatorCar로 분리 — y만 바꾸면 이동
 *   계단 난간 · 층 표시판
 *   교실: 칠판·교탁·책상 9·의자·사물함·청소함·TV·게시판·시계·쓰레기통 (열 간격 1.6m, 통로 1.05m)
 *   복도: 사물함·정수기·게시판·소화전·천장등 · 화장실: 칸 3·변기·세면대·거울
 *   계단: 실제 단 8개/플라이트 (챌판 0.225 · 디딤판 0.55) + 난간. 충돌은 아래 경사면 콜라이더가 담당
 *         (BOXES의 hide:true 항목 = 보이지 않는 경사 콜라이더 — 캐릭터가 매끄럽게 오른다)
 *   가구 디테일: 책상 다리·서랍칸, 의자 등받이, 사물함 문짝·손잡이, 칠판 분필받침,
 *                책장 선반판, 침대 베개·이불, 세면대 수전
 * 체육관               : 무대(커튼·앞계단·창고문·조명트러스) · 관중석 3단(좌석·난간·통로계단)
 *                        코트 라인(농구/배구/배드민턴·센터서클·자유투서클) · 농구 골대 2(코트 양단)
 *                        배구 네트+지주 · 늑목 · 벽 패드 · 스코어보드 · 시계 · 현판 · 비상구등
 *                        천장 트러스 3 + 조명 9 · 볼카트 · 평균대 · 링 · 뜀틀 · 매트 · 벤치
 *                        2F 캣워크 → 본관 2F 브릿지 · 지붕
 * 운동장               : 잔디 + 축구 피치(센터서클·하프라인·페널티/골에어리어·코너아크) · 흙 트랙(레인선·출발선)
 *                        골대 2(네트·측면망) · 백네트 2 · 조명탑 4(헤드 격자) · 조회대(마이크·스피커·깃발 3)
 *                        스탠드(좌석 등받이·난간) · 음수대 3 · 배수구 · 철봉 · 모래사장(도움닫기·거리표시)
 *                        야외 농구코트(라인·백보드·림)
 * 놀이터               : 미끄럼틀 타워(사다리 6단·슬라이드 면·측벽·난간·지붕) · 공중 브릿지 난간
 *                        정글짐 2층 격자 가로대 · 그네(사슬·시트·보강 지주) · 시소 · 스프링 2 · 뺑뺑이
 *                        타이어 터널 3 · 등나무 쉼터(서까래 6·덩굴 5·벤치 등받이) · 모래 도구 · 안전 매트 2
 *                        낮은 말뚝 울타리 12 · 안내판 · 쓰레기통
 * 후문 골목           : S자 담장 미로 + 기와 캡 · 낙서/포스터 패널 5 · 벽 얼룩 4 · 실외기 2 · 배관·계량기 3
 *                        자전거 6 · 킥보드 · 가로등 하우징 4 · 아스팔트 이음선 3 · 물웅덩이 3 · 배수 그레이팅 3
 *                        쓰레기 집하장(막다른 방): 분리수거통 3 · 마대 2 · 안내판 · 볼라드 2 · 후문 현판
 * 정문·주차장         : 교문 철제 문짝 2 · 학교 현판 · 진입 횡단라인 5 · 과속방지턱 2
 *                        경비실(전면창·측창·출입문·카운터·처마·실외기·명판, 지붕 오를 수 있음)
 *                        차량 3(캐빈 유리·바퀴 4·전조등·후미등) · 차막이 4 · 주차 번호 4 · 안전 거울
 *                        표지판 · 자전거 보관대 4 · 게시판 · 화단 경계석 · 우편함 · 맨홀 3
 * 놀이터 / 후문 골목(S자 담장 미로 + 막다른 집하장) / 정문·주차장(경비실 지붕)
 *
 * ── 수직 동선 (추격 루프의 핵심) ──
 * 1) 중앙 계단실(교실 밴드 베이)  1F↔3F↔옥상 펜트하우스
 * 2) 동쪽 계단실                 1F↔3F↔옥상
 * 3) 윙 계단실                   1F↔3F↔옥상
 * 4) 외부 비상계단(본관 동쪽 면)   1F→옥상 직행 숏컷
 * 5) 체육관 관중석 → 동쪽 계단 → 캣워크 → 2F 브릿지 → 본관 2F
 * 6) 본관 옥상 → 경사 다리 → 체육관 지붕
 * 7) 실외: 조회대 / 스탠드 / 놀이터 브릿지 / 등나무 지붕 / 경비실 지붕 / 옥상 기계실
 *
 * ── 가구·비품 ──
 * 교실 6 (칠판·교탁·책상 9·사물함) · 과학실 · 도서실 · 급식실 · 음악실 · 미술실 · 컴퓨터실
 * 시청각실 · 방송실 · 행정실 · 보건실 · 현관 로비 · 창고
 * 복도: 사물함·정수기·소화기·창문 | 체육관: 커튼·매트·뜀틀·네트·고창 | 옥상: 물탱크·기계실·실외기
 *
 * ── 검증 (campus-data.js + validate-map.js) ──
 * 램프 35개 양끝 착지 OK · 계단 착지 두상 OK
 * 지지면 포함 0.9m 캡슐 BFS: 1~3F 복도 → 계단 착지 3곳 전부 도달, 옥상 펜트하우스 문 3곳 도달
 * 계단실 개구부는 x·z 양축으로 한정 — 복도측 띠가 항상 남아 착지→층 연결 보장
 * 순찰 웨이포인트 19 · 스폰 3 · 트랩 12 · 프롭 10 모두 솔리드 밖 + 지지면 위 검증
 * 계단은 복도가 아닌 전용 베이 안에 있어 복도 폭을 잠식하지 않음
 *
 * ── 물리 주의 ──
 * 계단·경사면 16.7~26.6°. maxSlopeClimbAngle >= 0.52 rad 권장.
 * 예외: 놀이터 미끄럼틀 38° — 하강 전용.
 * 게임플레이: 트랩 12(gap/shortcut/deadend/vertical, 한 판 4~5개) · 게이트 3(한 판 1개)
 *   T1 미션 열쇠 후보 3(prop_sci_01/02·prop_class_01, 정답 1개 랜덤) · 프롭 슬롯 10
 *   조명 톤 14 (warm 운동장·놀이터 / amber 골목·정문 / cool 건물)
 *   pickRound(seed) 하나로 트랩·게이트·열쇠가 결정적으로 정해진다
 */
