/**
 * 엘리베이터 — 승강로는 층 바닥이 없는 관통 구조. 카는 ElevatorCar를 kinematic으로 올리고 내린다.
 * 상층 승강장에는 0.3m 문턱만 있으므로 카가 없는 층에서 문으로 들어가면 승강로로 추락한다(게임 연출로 활용 가능).
 */
export const ELEVATOR = {
  shaft: { x: [-22.35, -19.65] as V2, z: [-25.2, -22.55] as V2 },
  car: { center: [-21, -23.85] as V2, w: 2, d: 2.2, h: 2.25 },
  door: { centerX: -21, width: 1.2, z: -25.2 },
  stops: [{ floor: 'F1' as FloorKey, y: 0 }, { floor: 'F2' as FloorKey, y: 3.6 }, { floor: 'F3' as FloorKey, y: 7.2 }],
  speed: 1.2,
}

/** 카 구성 파츠 — 좌표는 카 원점(ELEVATOR.car.center) 기준 상대값 */
const CAR_PARTS: { p: V3; s: V3; c: string; visual?: boolean }[] = [
  { p: [0, -0.06, 0], s: [2, 0.12, 2.2], c: '#4a555f' },
  { p: [0, 2.31, 0], s: [2, 0.12, 2.2], c: '#2c3641' },
  { p: [0, 1.125, 1.05], s: [2, 2.25, 0.1], c: '#37424d' },
  { p: [-0.95, 1.125, 0], s: [0.1, 2.25, 2.2], c: '#37424d' },
  { p: [0.95, 1.125, 0], s: [0.1, 2.25, 2.2], c: '#37424d' },
  { p: [0, 1.5, 0.98], s: [1.5, 1.5, 0.04], c: '#33424e', visual: true },
  { p: [0, 0.92, 0.96], s: [1.6, 0.06, 0.06], c: '#8f979d', visual: true },
  { p: [0.86, 1.15, -0.5], s: [0.05, 1, 0.26], c: '#5a6a78', visual: true },
  { p: [0, 2.19, 0], s: [1.1, 0.06, 0.5], c: '#eaf4ff', visual: true },
  { p: [0, 1.93, -1.02], s: [0.6, 0.22, 0.05], c: '#2c3a46', visual: true },
  { p: [-0.5, 1.1, -1.06], s: [0.94, 2.2, 0.06], c: '#43505c', visual: true },
  { p: [0.5, 1.1, -1.06], s: [0.94, 2.2, 0.06], c: '#43505c', visual: true },

]

/** 엘리베이터 카 — y에 현재 카 바닥 높이를 넘긴다 (예: FLOOR_Y[cur])
 *  visual: true 파츠(문짝·거울·손잡이·조작반·조명·층표시)는 메시만 — 콜라이더를 만들지 않는다.
 *  colliders={false} + 명시적 CuboidCollider: 그래야 북면 출입구(1.8m)가 열린 상태로 유지된다. */
export function ElevatorCar({ y = 0, doorsOpen = true }: { y?: number; doorsOpen?: boolean }) {
  const [cx, cz] = ELEVATOR.car.center
  return (
    <RigidBody type="kinematicPosition" position={[cx, y, cz]} colliders={false}>
      {CAR_PARTS.filter((p) => !p.visual).map((p, i) => (
        <CuboidCollider key={`c${i}`} args={[p.s[0] / 2, p.s[1] / 2, p.s[2] / 2]} position={p.p} />
      ))}
      {CAR_PARTS.map((p, i) => {
        const isDoor = p.c === '#43505c'
        return (
          <mesh
            key={i}
            visible={!isDoor || !doorsOpen}
            position={isDoor && doorsOpen ? [p.p[0] * 1.95, p.p[1], p.p[2]] : p.p}
          >
            <boxGeometry args={p.s} />
            <meshStandardMaterial color={p.c} emissive={p.c} emissiveIntensity={p.c === '#eaf4ff' ? 0.9 : 0} />
          </mesh>
        )
      })}
    </RigidBody>
  )
}

export type TrapKind = 'gap' | 'shortcut' | 'deadend' | 'vertical'

/** 트랩 슬롯 12곳 — 한 판에 4~5개만 활성화 (pickRound 참조)
 *  gap 병목 · shortcut 지름길의 대가 · deadend 막다른 곳(최악) · vertical 수직 루트 고립 */
const TRAP_METADATA: { id: string; p: V2; floor: FloorKey; kind: TrapKind; risk: 1 | 2 | 3 }[] = [
  { id: 'trap_1f_corridor', p: [-8, -27.2], floor: 'F1', kind: 'gap', risk: 2 }, // 1F 중앙 복도 — 교실 문 사이 병목
  { id: 'trap_2f_science', p: [-9.5, -27.2], floor: 'F2', kind: 'gap', risk: 3 }, // 과학실(미션 방) 앞 — 미션 동선 필수 통과
  { id: 'trap_1f_kitchen', p: [-25.1, -19], floor: 'F1', kind: 'gap', risk: 2 }, // 급식실 앞 복도 — 윙 진입 병목
  { id: 'trap_field_gate', p: [13.5, 22], floor: 'OUT', kind: 'gap', risk: 2 }, // 운동장↔골목 개구부
  { id: 'trap_field_diag', p: [2, 6], floor: 'OUT', kind: 'shortcut', risk: 1 }, // 운동장 대각 지름길 — 지름길의 대가
  { id: 'trap_alley_curve', p: [-2.5, 30.5], floor: 'OUT', kind: 'shortcut', risk: 2 }, // 골목 S커브 — 시야 사각
  { id: 'trap_gym_stage', p: [21, -27], floor: 'F1', kind: 'shortcut', risk: 2 }, // 체육관 무대 앞 횡단
  { id: 'trap_1f_storage', p: [-21, -12.5], floor: 'F1', kind: 'deadend', risk: 3 }, // 창고 막다른 방 입구 — 최악
  { id: 'trap_gym_bleacher', p: [27.5, -31.5], floor: 'F1', kind: 'deadend', risk: 3 }, // 관중석 아래 — 빠져나갈 길 없음
  { id: 'trap_3f_end', p: [5.5, -27.2], floor: 'F3', kind: 'deadend', risk: 3 }, // 3F 복도 동쪽 끝 — 되돌아갈 수밖에
  { id: 'trap_play_bridge', p: [-27.4, 2], floor: 'OUT', kind: 'vertical', risk: 2 }, // 놀이터 공중 브릿지 — 내려갈 길 하나
  { id: 'trap_roof_tank', p: [-2, -33.5], floor: 'ROOF', kind: 'vertical', risk: 3 }, // 옥상 물탱크 사이 — 최상층 고립

]

/** 위치와 층은 서버도 읽는 공통 계약을 정본으로 사용한다. */
export const TRAP_SLOTS = TRAP_METADATA.map((metadata) => {
  const contract = trapContract.traps.find((trap) => trap.id === metadata.id)
  if (!contract) throw new Error(`Missing trap contract: ${metadata.id}`)
  return {
    ...metadata,
    p: [contract.x, contract.z] as V2,
    floor: contract.floor as FloorKey,
  }
})

