/** ══ T1 미션 (열쇠 찾기) ══
 *  후보 프롭 3개 중 정답 1개를 판마다 랜덤. 셋 다 같은 외형이라 조사해야 알 수 있다 */
export const MISSION = {
  id: 'T1_key',
  label: '열쇠를 찾아 탈출 게이트를 열어라',
  candidates: ['prop_sci_01', 'prop_sci_02', 'prop_class_01'] as const,
  searchSeconds: 1.6,
  revealRadius: 3.5,
}

/** ══ 라운드 구성 규칙 ══ */
export const ROUNDS = {
  trapCount: [4, 5] as const,
  trapMix: {"gap":[1,2],"shortcut":[1,2],"deadend":[1,2],"vertical":[0,1]} as Record<TrapKind, [number, number]>,
  gateCount: 1,
}

export type RoundPlan = { seed: number; traps: string[]; gate: string; missionProp: string; decoyProps: string[] }

/** 시드 → 판 구성 (결정적: 서버·클라이언트 동일 결과).
 *  트랩은 카테고리 최소치를 먼저 채워 병목만 몰리는 판을 막는다 */
export function pickRound(seed: number = Date.now()): RoundPlan {
  let x = seed >>> 0 || 1
  const rnd = () => ((x = (x * 1664525 + 1013904223) >>> 0) / 4294967296)
  const shuffle = <T,>(a: readonly T[]): T[] => {
    const r = a.slice()
    for (let i = r.length - 1; i > 0; i--) { const j = Math.floor(rnd() * (i + 1)); [r[i], r[j]] = [r[j], r[i]] }
    return r
  }
  const [lo, hi] = ROUNDS.trapCount
  const target = lo + Math.floor(rnd() * (hi - lo + 1))
  const chosen: typeof TRAP_SLOTS = []
  for (const kind of Object.keys(ROUNDS.trapMix) as TrapKind[]) {
    const pool = shuffle(TRAP_SLOTS.filter((t) => t.kind === kind))
    for (let i = 0; i < ROUNDS.trapMix[kind][0] && i < pool.length; i++) chosen.push(pool[i])
  }
  for (const t of shuffle(TRAP_SLOTS.filter((t) => !chosen.includes(t)))) {
    if (chosen.length >= target) break
    if (chosen.filter((c) => c.kind === t.kind).length < ROUNDS.trapMix[t.kind][1]) chosen.push(t)
  }
  const gate = shuffle(GATE_SLOTS)[0].id
  const missionProp = shuffle(MISSION.candidates)[0]
  return {
    seed, traps: chosen.map((t) => t.id), gate, missionProp,
    decoyProps: MISSION.candidates.filter((c) => c !== missionProp) as string[],
  }
}

export function TrapPlate({ id, position, floor, active = true, onTriggered }: {
  id: string; position: V2; floor: FloorKey; active?: boolean; onTriggered?: (id: string) => void
}) {
  if (!active) return null
  const y = FLOOR_Y[floor]
  return (
    <RigidBody type="fixed" position={[position[0], y, position[1]]} colliders={false}>
      <CuboidCollider args={[0.75, 0.14, 0.75]} sensor onIntersectionEnter={() => onTriggered?.(id)} />
      <mesh position={[0, 0.04, 0]}>
        <boxGeometry args={[1.5, 0.07, 1.5]} />
        {/* 어둠 속 아주 희미한 발광 — 아는 사람만 피한다 */}
        <meshStandardMaterial color="#33121c" emissive="#FF2F6E" emissiveIntensity={0.12} />
      </mesh>
    </RigidBody>
  )
}

export function GateFrame({ position, rotationY, selected = false, open = false, onActivated, onArrived, onEscaped }: {
  position: V2; rotationY: number
  /** 서버가 선택한 이번 판의 게이트. final_spell부터 잠긴 상태로 노출한다. */
  selected?: boolean
  /** 주문 성공 뒤 실제로 열린 상태. */
  open?: boolean
  onActivated?: () => void
  onArrived?: () => void
  onEscaped?: () => void
}) {
  const beamRef = useRef<THREE.Mesh>(null)
  const prev = useRef(open)
  useEffect(() => {
    if (open && !prev.current) onActivated?.()
    prev.current = open
  }, [open, onActivated])
  // 선택된 게이트는 잠긴 동안 황색, 주문 성공 뒤 청록색 비콘으로 안내한다.
  useFrame((st) => {
    if (!beamRef.current) return
    const t = st.clock.elapsedTime
    const m = beamRef.current.material as THREE.MeshBasicMaterial
    m.opacity = selected
      ? (open ? 0.16 + 0.1 * Math.sin(t * 2.2) : 0.08 + 0.04 * Math.sin(t * 1.8))
      : 0
    beamRef.current.scale.y = selected ? 1 + 0.04 * Math.sin(t * 1.6) : 0.001
  })
  const glow = open ? 1.3 : selected ? 0.55 : 0.12
  const gateColor = open ? '#52E5FF' : selected ? '#FFD166' : '#52E5FF'
  return (
    <group position={[position[0], 0, position[1]]} rotation={[0, rotationY, 0]}>
      {!open && (
        <RigidBody type="fixed" colliders={false}>
          <CuboidCollider args={GATE_LOCKED_BLOCKER_HALF_SIZE} position={[0, 1.5, 0]} />
          <mesh position={[0, 1.5, 0]}>
            <boxGeometry args={[2.6, 3, 0.24]} />
            <meshStandardMaterial color="#171f27" emissive={gateColor}
              emissiveIntensity={selected ? 0.28 : 0.04} transparent opacity={0.88} />
          </mesh>
        </RigidBody>
      )}
      {selected && !open && (
        <RigidBody type="fixed" colliders={false}>
          <CuboidCollider args={[1.4, 1.5, 1.0]} position={[0, 1.5, GATE_SENSOR_LOCAL_Z.arrival]}
            sensor onIntersectionEnter={onArrived} />
        </RigidBody>
      )}
      {selected && open && (
        <RigidBody type="fixed" colliders={false}>
          <CuboidCollider args={[1.15, 1.5, 0.7]} position={[0, 1.5, GATE_SENSOR_LOCAL_Z.escape]}
            sensor onIntersectionEnter={onEscaped} />
        </RigidBody>
      )}
      {/* 탈출 지점 표식 — 멀리서도 보이는 빛기둥 (활성 시에만) */}
      <mesh ref={beamRef} position={[0, 6, 0]}>
        <cylinderGeometry args={[1.5, 1.5, 12, 12, 1, true]} />
        <meshBasicMaterial color={gateColor} transparent opacity={0} depthWrite={false}
          side={THREE.DoubleSide} fog={false} />
      </mesh>
      {selected && <pointLight position={[0, 2.6, 0]} intensity={open ? 14 : 6}
        distance={9} decay={1.5} color={gateColor} />}
      {([-1.5, 1.5] as const).map((x) => (
        <RigidBody key={x} type="fixed" position={[x, 1.7, 0]} colliders="cuboid">
          <mesh>
            <cylinderGeometry args={[0.18, 0.18, 3.4, 10]} />
            <meshStandardMaterial color="#3a3a5a" emissive={gateColor} emissiveIntensity={glow} />
          </mesh>
        </RigidBody>
      ))}
      <mesh position={[0, 3.3, 0]}>
        <boxGeometry args={[3.3, 0.34, 0.34]} />
        <meshStandardMaterial color="#3a3a5a" emissive={gateColor} emissiveIntensity={glow} />
      </mesh>
    </group>
  )
}

export function Lamp({ position, h, color, dynamicLight = true }: {
  position: V2
  h: number
  color: string
  dynamicLight?: boolean
}) {
  return (
    <group position={[position[0], 0, position[1]]}>
      <RigidBody type="fixed" position={[0, h / 2, 0]} colliders="cuboid">
        <mesh>
          <cylinderGeometry args={[0.08, 0.08, h, 8]} />
          <meshStandardMaterial color="#5a5a5a" />
        </mesh>
      </RigidBody>
      <mesh position={[0, h - 0.1, 0]}>
        <coneGeometry args={[0.34, 0.28, 8]} />
        <meshStandardMaterial color="#5a5a5a" emissive={color} emissiveIntensity={0.9} />
      </mesh>
      {dynamicLight && (
        <pointLight position={[0, h - 0.3, 0]} intensity={h > 5 ? 9 : 5}
          distance={h > 5 ? 20 : 13} decay={1.6} color={color} />
      )}
    </group>
  )
}

/* ── InstancedMesh 배칭 ── */
function BoxInstances({ boxes }: { boxes: typeof BOXES }) {
  const groups = useMemo(() => {
    const m = new Map<string, typeof BOXES>()
    for (const b of boxes) {
      if (b.hide) continue
      const arr = m.get(b.c)
      if (arr) arr.push(b)
      else m.set(b.c, [b])
    }
    return m
  }, [boxes])

  return (
    <>
      {Array.from(groups.entries()).map(([color, items]) => (
        <BoxColorBatch key={color} items={items} color={color} />
      ))}
    </>
  )
}

function BoxColorBatch({ items, color }: { items: typeof BOXES; color: string }) {
  const ref = useRef<THREE.InstancedMesh>(null)
  useEffect(() => {
    if (!ref.current) return
    const mat = new THREE.Matrix4()
    const pos = new THREE.Vector3()
    const quat = new THREE.Quaternion()
    const scl = new THREE.Vector3()
    const euler = new THREE.Euler()
    for (let i = 0; i < items.length; i++) {
      const b = items[i]
      pos.set(b.p[0], b.p[1], b.p[2])
      scl.set(b.s[0], b.s[1], b.s[2])
      if (b.rot) { euler.set(b.rot[0], b.rot[1], b.rot[2]); quat.setFromEuler(euler) }
      else quat.identity()
      mat.compose(pos, quat, scl)
      ref.current.setMatrixAt(i, mat)
    }
    ref.current.instanceMatrix.needsUpdate = true
  }, [items])

  return (
    <instancedMesh ref={ref} args={[undefined, undefined, items.length]} frustumCulled={false}>
      <boxGeometry args={[1, 1, 1]} />
      <meshStandardMaterial color={color} />
    </instancedMesh>
  )
}

function VisualBoxInstances({ items }: { items: typeof VISUALS }) {
  const groups = useMemo(() => {
    const m = new Map<string, typeof VISUALS>()
    for (const v of items) {
      if (v.t !== 'box') continue
      const arr = m.get(v.c)
      if (arr) arr.push(v)
      else m.set(v.c, [v])
    }
    return m
  }, [items])

  return (
    <>
      {Array.from(groups.entries()).map(([color, group]) => (
        <VisualBoxColorBatch key={color} items={group} color={color} />
      ))}
    </>
  )
}

function VisualBoxColorBatch({ items, color }: { items: typeof VISUALS; color: string }) {
  const ref = useRef<THREE.InstancedMesh>(null)
  useEffect(() => {
    if (!ref.current) return
    const mat = new THREE.Matrix4()
    const pos = new THREE.Vector3()
    const quat = new THREE.Quaternion()
    const scl = new THREE.Vector3()
    const euler = new THREE.Euler()
    for (let i = 0; i < items.length; i++) {
      const v = items[i]
      pos.set(v.p[0], v.p[1], v.p[2])
      const s = v.s as V3 | undefined
      scl.set(s ? s[0] : 1, s ? s[1] : 1, s ? s[2] : 1)
      if (v.rot) { euler.set(v.rot[0], v.rot[1], v.rot[2]); quat.setFromEuler(euler) }
      else quat.identity()
      mat.compose(pos, quat, scl)
      ref.current.setMatrixAt(i, mat)
    }
    ref.current.instanceMatrix.needsUpdate = true
  }, [items])

  return (
    <instancedMesh ref={ref} args={[undefined, undefined, items.length]} frustumCulled={false}>
      <boxGeometry args={[1, 1, 1]} />
      <meshStandardMaterial color={color} />
    </instancedMesh>
  )
}

export default function SchoolCampus({ visibleFloors, activeTraps, gateId, gateOpen = false, onTrapEnter, onGateArrive, onGateEscape, elevatorY = 0 }: {
  visibleFloors?: FloorKey[]
  activeTraps?: string[]
  gateId?: string
  gateOpen?: boolean
  onTrapEnter?: (id: string) => void
  onGateArrive?: (id: string) => void
  onGateEscape?: (id: string) => void
  elevatorY?: number
}) {
  const show = useCallback(
    (f: FloorKey) => !visibleFloors || visibleFloors.includes(f),
    [visibleFloors],
  )

  const filteredBoxes = useMemo(
    () => BOXES.filter((b) => show(b.f)),
    [show],
  )
  const filteredCyls = useMemo(
    () => CYLS.filter((c) => show(c.f)),
    [show],
  )
  const filteredVisuals = useMemo(
    () => VISUALS.filter((v) => show(v.f)),
    [show],
  )
  const nonBoxVisuals = useMemo(
    () => filteredVisuals.filter((v) => v.t !== 'box'),
    [filteredVisuals],
  )

  return (
    <group>
      {/* 지면 */}
      <RigidBody type="fixed" position={[0, -0.5, 0]}>
        <mesh>
          <boxGeometry args={[MAP_SIZE + 4, 1, MAP_SIZE + 4]} />
          <meshStandardMaterial color="#0c1117" />
        </mesh>
      </RigidBody>

      {/* ── BOXES: compound collider 1개 + InstancedMesh per color ── */}
      <RigidBody type="fixed" colliders={false}>
        {filteredBoxes.map((b, i) => (
          <CuboidCollider key={i}
            args={[b.s[0] / 2, b.s[1] / 2, b.s[2] / 2]}
            position={b.p} rotation={b.rot}
          />
        ))}
      </RigidBody>
      <BoxInstances boxes={filteredBoxes} />

      {/* ── CYLS: compound collider 1개 + 개별 mesh (114개라 배칭 불필요) ── */}
      <RigidBody type="fixed" colliders={false}>
        {filteredCyls.map((cy, i) => (
          <CuboidCollider key={i}
            args={[cy.r, cy.h / 2, cy.r]}
            position={cy.p} rotation={cy.rot}
          />
        ))}
      </RigidBody>
      {filteredCyls.map((cy, i) => (
        <mesh key={`c${i}`} position={cy.p} rotation={cy.rot}>
          <cylinderGeometry args={[cy.r, cy.r, cy.h, 8]} />
          <meshStandardMaterial color={cy.c} />
        </mesh>
      ))}

      {/* ── VISUALS box: InstancedMesh per color ── */}
      <VisualBoxInstances items={filteredVisuals} />

      {/* ── VISUALS 비-box: 개별 mesh (168개 — 배칭 대비 공수 과다) ── */}
      {nonBoxVisuals.map((v, i) =>
        v.t === 'sph' ? (
          <mesh key={`v${i}`} position={v.p}>
            <sphereGeometry args={[v.r!, 8, 6]} />
            <meshStandardMaterial color={v.c} />
          </mesh>
        ) : v.t === 'plate' ? (
          <mesh key={`v${i}`} position={v.p} rotation={[-Math.PI / 2, 0, 0]}>
            <planeGeometry args={v.s as [number, number]} />
            <meshStandardMaterial color={v.c} />
          </mesh>
        ) : v.t === 'ring' ? (
          <mesh key={`v${i}`} position={v.p} rotation={[-Math.PI / 2, 0, 0]} scale={[v.sx!, v.sz!, 1]}>
            <ringGeometry args={[v.ri!, v.ro!, 32]} />
            <meshBasicMaterial color={v.c} side={2} />
          </mesh>
        ) : (
          <mesh key={`v${i}`} position={v.p} rotation={v.rot}>
            <cylinderGeometry args={[v.r!, v.r!, v.h!, 8]} />
            <meshStandardMaterial color={v.c} />
          </mesh>
        )
      )}

      {TRAP_SLOTS.filter((t) => show(t.floor)).map((t) => (
        <TrapPlate key={t.id} id={t.id} position={t.p} floor={t.floor}
          active={!activeTraps || activeTraps.includes(t.id)} onTriggered={onTrapEnter} />
      ))}

      {GATE_SLOTS.map((g) => (
        <GateFrame key={g.id} position={g.p} rotationY={g.ry} selected={g.id === gateId}
          open={g.id === gateId && gateOpen}
          onArrived={() => onGateArrive?.(g.id)}
          onEscaped={() => onGateEscape?.(g.id)} />
      ))}

      {LAMPS.map((l, i) => (
        <Lamp key={`l${i}`} position={l.p} h={l.h} color={l.c}
          dynamicLight={i % 5 < 2} />
      ))}

      <ElevatorCar y={elevatorY} />

    </group>
  )
}
